function resetAd(){if(!$('adForm'))return;$('adForm').reset();document.querySelectorAll('input[name="adPlacement"]').forEach(x=>x.checked=false);$('adAnimation').checked=false;$('adAnimationType').value='fade';$('adSlider').checked=false;$('adSliderInterval').value='3000';$('adVideoPreview')?.classList.add('hidden');$('adVideoPreview')?.removeAttribute('src');$('adId').value='';$('adStart').value=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);$('adPrice').value='0';say('adMessage','')}
