async function loadArticleAdInventory(){
 const box=$('articleAdRows');if(!box||currentRole!=='admin')return;
 box.innerHTML='<tr><td colspan="4">লোড হচ্ছে…</td></tr>';
 const {data,error}=await db.from('articles').select('id,title,status,ad_slots').order('created_at',{ascending:false}).limit(500);
 if(error){box.innerHTML='<tr><td colspan="4">সংবাদ বিজ্ঞাপন তালিকা পাওয়া যায়নি: '+esc(error.message)+'</td></tr>';return}
 const pos={before:'সংবাদের শুরুতে',after:'সংবাদের শেষে',in_content:'সংবাদের ভেতরে',after_paragraph:'নির্দিষ্ট অনুচ্ছেদের পরে'};
 const kind={image:'ছবি',video:'ভিডিও',html:'HTML/JavaScript',link:'লিংক'};
 const rows=[];
 (data||[]).forEach(article=>{
  const slots=Array.isArray(article.ad_slots)?article.ad_slots:[];
  slots.forEach((slot,index)=>{
   rows.push('<tr><td><b>'+esc(article.title||('সংবাদ #'+article.id))+'</b><br><small>ID: '+esc(article.id)+'</small></td><td>'+esc(kind[slot.kind]||slot.kind||'বিজ্ঞাপন')+'</td><td>'+esc(pos[slot.position]||slot.position||'সংবাদের ভেতরে')+(slot.position==='after_paragraph'?' ('+Number(slot.paragraph||3)+' নম্বর অনুচ্ছেদ)':'')+'</td><td>'+esc(article.status||'—')+'</td></tr>');
  });
 });
 box.innerHTML=rows.join('')||'<tr><td colspan="4">এখনো কোনো সংবাদের সঙ্গে বিজ্ঞাপন যুক্ত নেই। সংবাদ পরিচালনা বিভাগ থেকে বিজ্ঞাপন যোগ করলে এখানে দেখা যাবে।</td></tr>';
}
async function loadAds(){const box=$('adRows');if(!box||currentRole!=='admin')return;const {data,error}=await db.from('ad_campaigns').select('*').order('created_at',{ascending:false}).limit(300);if(error){box.innerHTML='<tr><td colspan="6">'+esc(error.message)+'</td></tr>';return}const p={header:'হেডার',top:'হোমপেজ ব্যানার',side:'সাইডবার',side_tall:'সাইডবারের নিচে (লম্বা বিজ্ঞাপন)',feed:'সংবাদের ফিডের মধ্যে',bottom:'ফুটার',article:'নির্দিষ্ট সংবাদ'},s={draft:'খসড়া',active:'চালু',paused:'স্থগিত',expired:'মেয়াদ শেষ'},pay={unpaid:'বাকি',partial:'আংশিক',paid:'পরিশোধিত'};box.innerHTML=(data||[]).map(a=>'<tr><td><b>'+esc(a.advertiser_name)+'</b><br>'+esc(a.title)+'<br><small>'+(a.ad_type==='network'?'নেটওয়ার্ক':'নিজস্ব')+'</small></td><td>'+String(a.placement||'').split(',').map(v=>p[v]||v).join(', ')+'</td><td>'+adDate(a.start_at)+'<br>শেষ: '+adDate(a.end_at)+'</td><td>'+Number(a.price||0).toLocaleString('bn-BD')+' টাকা<br>'+(pay[a.payment_status]||a.payment_status)+'</td><td>'+(s[a.status]||a.status)+'</td><td><button class="btn" data-ad-edit="'+a.id+'">সম্পাদনা</button> <button class="btn btn-light" data-ad-toggle="'+a.id+'">'+(a.status==='active'?'স্থগিত':'চালু')+'</button> <button class="btn btn-red" data-ad-delete="'+a.id+'">মুছুন</button></td></tr>').join('')||'<tr><td colspan="6">এখনো কোনো বিজ্ঞাপন নেই।</td></tr>';box.querySelectorAll('[data-ad-edit]').forEach(b=>b.onclick=()=>editAd(data.find(a=>String(a.id)===b.dataset.adEdit)));box.querySelectorAll('[data-ad-toggle]').forEach(b=>b.onclick=async()=>{const a=data.find(x=>String(x.id)===b.dataset.adToggle);const {error}=await db.from('ad_campaigns').update({status:a.status==='active'?'paused':'active'}).eq('id',a.id);if(error)toast(error.message);else loadAds()});box.querySelectorAll('[data-ad-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('বিজ্ঞাপন মুছবেন?'))return;const {error}=await db.from('ad_campaigns').delete().eq('id',b.dataset.adDelete);if(error)toast(error.message);else loadAds()})}
function editAd(a){$('adId').value=a.id;$('adAdvertiser').value=a.advertiser_name;$('adTitle').value=a.title;$('adType').value='direct';document.querySelectorAll('input[name="adPlacement"]').forEach(x=>x.checked=String(a.placement||'').split(',').includes(x.value));let motion={};try{motion=JSON.parse(a.embed_code||'{}')}catch{};$('adAnimation').checked=!!motion.animation;$('adAnimationType').value=motion.animation_type||'fade';$('adSlider').checked=!!motion.slider;$('adSliderInterval').value=String(motion.slider_interval||3000);$('adImage').value=a.image_url||'';$('adImageFile').value='';if(a.image_url){$('adImagePreview').src=a.image_url;$('adImagePreview').classList.remove('hidden')}else $('adImagePreview').classList.add('hidden');$('adTarget').value=a.target_url||'';$('adEmbed').value=a.embed_code||'';const dt=v=>v?new Date(new Date(v).getTime()-new Date(v).getTimezoneOffset()*60000).toISOString().slice(0,16):'';$('adStart').value=dt(a.start_at);$('adEnd').value=dt(a.end_at);$('adPrice').value=a.price||0;$('adPayment').value=a.payment_status;$('adStatus').value=a.status;$('adArticle').value=a.article_id||'';document.querySelector('[data-tab="ads"]').click()}
$('adReset')?.addEventListener('click',resetAd);$('refreshAds')?.addEventListener('click',loadAds);$('refreshArticleAds')?.addEventListener('click',loadArticleAdInventory);
$('adForm')?.addEventListener('submit',async e=>{e.preventDefault();if(currentRole!=='admin')return;try{const id=$('adId').value;let adImage=$('adImage').value.trim();const adFile=$('adImageFile')?.files[0],adVideo=$('adVideoFile')?.files[0];if(adFile&&adVideo)throw new Error('ছবি অথবা ভিডিও—একটি মিডিয়া নির্বাচন করুন।');if(adFile)adImage=await uploadImage(adFile,'ads');if(adVideo)adImage=await uploadVideo(adVideo,'ads');const placements=[...document.querySelectorAll('input[name="adPlacement"]:checked')].map(x=>x.value);if(!placements.length)throw new Error('কমপক্ষে একটি বিজ্ঞাপন প্রদর্শনের স্থান নির্বাচন করুন।');if(placements.includes('article')&&placements.length>1)throw new Error('নির্দিষ্ট সংবাদ বিজ্ঞাপন একক স্থানেই নির্বাচন করুন।');const payload={advertiser_name:$('adAdvertiser').value.trim(),title:$('adTitle').value.trim(),ad_type:'direct',placement:placements.join(','),image_url:adImage||null,target_url:$('adTarget').value.trim()||null,embed_code:JSON.stringify({animation:$('adAnimation').checked,animation_type:$('adAnimationType').value,slider:$('adSlider').checked,slider_interval:Number($('adSliderInterval').value||3000),placement_sizes:Object.fromEntries([...document.querySelectorAll('[data-placement-size]')].filter(x=>placements.includes(x.dataset.placementSize)).map(x=>[x.dataset.placementSize,x.value]))}),start_at:new Date($('adStart').value).toISOString(),end_at:$('adEnd').value?new Date($('adEnd').value).toISOString():null,price:Number($('adPrice').value||0),payment_status:$('adPayment').value,status:$('adStatus').value,article_id:$('adArticle').value?Number($('adArticle').value):null,updated_at:new Date().toISOString()};if(placements.includes('article')&&!payload.article_id)throw Error('নির্দিষ্ট সংবাদ বিজ্ঞাপনের জন্য সংবাদ ID দিন।');if(payload.end_at&&payload.end_at<=payload.start_at)throw Error('শেষের সময় শুরুর সময়ের পরে দিন।');if(!payload.image_url)throw Error('সরাসরি বিজ্ঞাপনের ছবি দিন।');if(payload.status==='active'&&!confirm('বিজ্ঞাপনদাতা, ছবি ও লেখা যাচাই করেছেন? গন্তব্য লিংক দেওয়া থাকলে সেটিও যাচাই করেছেন? অনুমোদন করে প্রকাশ করবেন?'))return;if(payload.ad_type==='network'&&!payload.embed_code&&!payload.target_url&&!payload.image_url)throw Error('নেটওয়ার্কের কোড, বিজ্ঞাপনের ছবি বা গন্তব্য লিংক দিন।');const r=id?await db.from('ad_campaigns').update(payload).eq('id',id):await db.from('ad_campaigns').insert(payload);if(r.error)throw r.error;resetAd();say('adMessage','বিজ্ঞাপন সংরক্ষিত হয়েছে।');await loadAds()}catch(err){say('adMessage','ব্যর্থ: '+err.message,true)}});
async function loadAll(){if(currentRole==='admin'){await Promise.all([loadAnalytics(),loadCategories(),loadPosts(),loadVideos(),loadSettings(),loadCommentsAdmin(),loadOpinionsAdmin(),loadStaff(),loadAiQueue(),loadAiSourceHealth(),loadAds(),loadArticleAdInventory()])}else{await Promise.all([loadPosts(),loadVideos()])}}
async function loadAnalytics(){if(!$('statVisitors'))return;const [v,p,c]=await Promise.all([db.from('site_visitors').select('visitor_id,page_views'),db.from('articles').select('id,title,views,status,published_at').eq('status','published').or('published_at.is.null,published_at.lte.'+new Date().toISOString()).order('views',{ascending:false}).limit(20),db.from('articles').select('id',{count:'exact',head:true}).eq('status','published').or('published_at.is.null,published_at.lte.'+new Date().toISOString())]);if(v.error){$('statVisitors').textContent='—';$('analyticsMessage').textContent='ভিজিটর ডেটা লোড হয়নি: '+v.error.message}else{$('statVisitors').textContent=Number(v.data?.length||0).toLocaleString('bn-BD');$('statPageViews').textContent=(v.data||[]).reduce((n,x)=>n+Number(x.page_views||0),0).toLocaleString('bn-BD')}if(p.error){$('statPublished').textContent='—';$('popularAdmin').innerHTML='<tr><td colspan="3">'+esc(p.error.message)+'</td></tr>';return}const rows=p.data||[];$('statPublished').textContent=Number(c.count||0).toLocaleString('bn-BD');$('popularAdmin').innerHTML=rows.map((x,i)=>'<tr><td>'+(i+1).toLocaleString('bn-BD')+'</td><td>'+esc(x.title)+'</td><td>'+Number(x.views||0).toLocaleString('bn-BD')+'</td></tr>').join('')||'<tr><td colspan="3">প্রকাশিত সংবাদ নেই।</td></tr>'}
